const rows = Array.isArray(msg.payload) ? msg.payload : [];
   const now = {};
   let drifted = 0;
   for (const row of rows) {
       // Der Vergleichsschlüssel ist Zustand plus Umfang: aus "clean" wird
       // "drifted", und aus 4 geänderten Zeilen werden 40 — beides ist eine
       // Änderung, eine unveränderte Drift ist keine.
       now[row.instance] = row.state === "drifted"
           ? `drifted:${row.changed_lines}`
           : row.state;
       if (row.state === "drifted") { drifted++; }
   }

   const before = flow.get("driftState") || {};
   flow.set("driftState", now);

   const stamp = new Date().toTimeString().slice(0, 5);
   const seen = `${stamp} · ${rows.length} Instanzen, ${drifted} drifted`;

   // Beim allerersten Lauf ist alles "neu" — das ist der Anfang der Messung,
   // kein Ereignis. Dasselbe nach einem Neustart: der Kontext liegt im
   // Speicher, also beginnt die Messung dort von vorn.
   if (!Object.keys(before).length) {
       node.status({ fill: "grey", shape: "ring", text: `${seen} · Startwert` });
       return null;
   }

   const changed = Object.keys(now)
       .filter(k => now[k] !== before[k])
       .map(k => `${k}: ${before[k] || "unbekannt"} → ${now[k]}`);

   if (!changed.length) {
       node.status({ fill: "green", shape: "dot", text: `${seen} · unverändert` });
       return null;
   }

   node.status({ fill: "yellow", shape: "dot", text: `${seen} · ${changed.length} Änderung(en)` });
   msg.payload = changed.join("\n");
   msg.topic = `Node-RED Drift: ${changed.length} Änderung(en)`;
   return msg;

// Node-RED Function node body
// External module: XLSX -> xlsx

const MAX_FILE_BYTES = 5 * 1024 * 1024;
const PREVIEW_PAGE_SIZE = 25;
const MAX_DETAIL_ITEMS = 100;
const CANDIDATE_TTL_MS = 30 * 60 * 1000;
const SITE_TABLES = {
    '2000': 'quality.foam_test_result_2000',
    '5000': 'quality.foam_test_result_5000',
    '8200': 'quality.foam_test_result_8200'
};
const LANGUAGES = new Set(['de', 'pl', 'ro']);

const FIELD_DEFS = [
    { key: 'supplier', requiredValue: true, aliases: ['Dostawca/Lieferant', 'Lieferant'] },
    { key: 'material_name', requiredValue: true, aliases: ['Nazwa_materiału/Bezeichnung', 'Bezeichnung'] },
    { key: 'sap_number', requiredValue: false, aliases: ['Nr_SAP', 'SAP-Nr'] },
    { key: 'batch_number', requiredValue: false, aliases: ['Nr_partii/Chragen-Nr', 'Nr_partii/Chargen-Nr', 'Chargen-Nr_'] },
    { key: 'production_date', requiredValue: false, aliases: ['Data_produkcji/Produktionsdatum', 'Produktionsdatum'] },
    { key: 'purchase_order_number', requiredValue: false, aliases: ['Nr_zamówienia_SAP/Bestell-Nr__SAP', 'Nr_zamówienia_SAP/SAP_Bestell-Nr', 'Bestell-Nr_SAP'] },
    { key: 'compression_hardness_kpa', requiredValue: true, aliases: ['Twardość/Stauchhaerte_(kPa)', 'Stauchhaerte_(kPa)\u00a0', 'Stauchhaerte_(kPa)'] },
    { key: 'density_kg_m3', requiredValue: true, aliases: ['Gęstość/Raumgewicht_(kg/m3)', 'Gęstość/Raumgewicht_(kg/m³)', 'Raumgewicht (kg/m3)', 'Raumgewicht (kg/m³)'] },
    { key: 'test_date', requiredValue: false, aliases: ['Data_badania/Pruef-Datum', 'Pruef-Datum'] },
    { key: 'plant', requiredValue: true, aliases: ['Zakład/Werk', 'Werk'] },
    { key: 'inspector', requiredValue: false, aliases: ['Badający/Pruefer', 'Pruefer'] },
    { key: 'remarks', requiredValue: false, aliases: ['Uwagi/Bemerkungen', 'Bemerkungen'] }
];

function normalizeHeader(value) {
    return String(value == null ? '' : value)
        .replace(/\u00a0/g, ' ')
        .replace(/³/g, '3')
        .normalize('NFKD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]/g, '');
}

const aliasMap = new Map();
for (const def of FIELD_DEFS) {
    for (const alias of def.aliases) aliasMap.set(normalizeHeader(alias), def.key);
}

function issue(level, code, row, field, value, params) {
    return {
        level,
        code,
        row: row == null ? null : row,
        field: field || null,
        value: value == null ? null : String(value).slice(0, 160),
        params: params || {}
    };
}

function isEmpty(value) {
    return value == null || (typeof value === 'string' && value.replace(/\u00a0/g, ' ').trim() === '');
}

function cleanText(value) {
    if (isEmpty(value)) return null;
    if (typeof value === 'number') {
        if (!Number.isFinite(value)) return null;
        return String(value);
    }
    if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString();
    return String(value)
        .replace(/\u00a0/g, ' ')
        .replace(/[\t\r\n]+/g, ' ')
        .replace(/ {2,}/g, ' ')
        .trim() || null;
}

function jsonSafe(value) {
    if (value == null) return null;
    if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString();
    if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
    if (typeof value === 'string' || typeof value === 'boolean') return value;
    try { return JSON.parse(JSON.stringify(value)); } catch (_) { return String(value); }
}

function parseNumber(value) {
    if (typeof value === 'number') return Number.isFinite(value) ? value : null;
    const raw = cleanText(value);
    if (raw == null) return null;
    let s = raw.replace(/\s/g, '');
    const comma = s.lastIndexOf(',');
    const dot = s.lastIndexOf('.');
    if (comma >= 0 && dot >= 0) {
        if (comma > dot) s = s.replace(/\./g, '').replace(',', '.');
        else s = s.replace(/,/g, '');
    } else if (comma >= 0) {
        s = s.replace(',', '.');
    }
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
}

function isoDate(y, m, d) {
    if (!Number.isInteger(y) || !Number.isInteger(m) || !Number.isInteger(d)) return null;
    const dt = new Date(Date.UTC(y, m - 1, d));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
    return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function parseDate(value, row, field, rowWarnings) {
    const raw = cleanText(value);
    if (raw == null) return { iso: null, raw: null };

    const marker = raw.toUpperCase();
    if (['BRAK', 'OHNE', 'MUSTER', '-'].includes(marker)) {
        rowWarnings.push(issue('warning', 'DATE_MISSING_MARKER', row, field, raw, { marker: raw }));
        return { iso: null, raw };
    }

    if (value instanceof Date && !Number.isNaN(value.getTime())) {
        const iso = value.toISOString().slice(0, 10);
        rowWarnings.push(issue('warning', 'DATE_OBJECT_NORMALIZED', row, field, raw, { normalized: iso }));
        return { iso, raw };
    }

    if (typeof value === 'number' && Number.isFinite(value)) {
        const dc = XLSX.SSF && XLSX.SSF.parse_date_code ? XLSX.SSF.parse_date_code(value) : null;
        const iso = dc ? isoDate(dc.y, dc.m, dc.d) : null;
        if (iso) {
            rowWarnings.push(issue('warning', 'DATE_SERIAL_NORMALIZED', row, field, value, { normalized: iso }));
            return { iso, raw };
        }
        rowWarnings.push(issue('warning', 'DATE_INVALID', row, field, value));
        return { iso: null, raw };
    }

    const compact = raw.replace(/\s/g, '');
    const normalizedSep = compact.replace(/[-,]/g, '.');
    const parts = normalizedSep.split('.');
    if (parts.length === 3 && parts.every(p => /^\d+$/.test(p))) {
        let a = Number(parts[0]);
        let b = Number(parts[1]);
        const y = Number(parts[2]);
        let d = a;
        let m = b;
        let mode = 'DMY';

        if (b > 12 && a >= 1 && a <= 12) {
            m = a;
            d = b;
            mode = 'MDY';
        }

        const iso = isoDate(y, m, d);
        if (iso) {
            if (mode === 'MDY') {
                rowWarnings.push(issue('warning', 'DATE_US_FORMAT_NORMALIZED', row, field, raw, { normalized: iso }));
            } else if (normalizedSep !== compact) {
                rowWarnings.push(issue('warning', 'DATE_SEPARATOR_NORMALIZED', row, field, raw, { normalized: iso }));
            }
            return { iso, raw };
        }
    }

    rowWarnings.push(issue('warning', 'DATE_INVALID', row, field, raw));
    return { iso: null, raw };
}

function compareIso(a, b) {
    if (!a || !b) return null;
    return a.localeCompare(b);
}

function makeSummary(items) {
    const map = new Map();
    for (const item of items) {
        if (!map.has(item.code)) map.set(item.code, { code: item.code, count: 0 });
        map.get(item.code).count += 1;
    }
    return Array.from(map.values()).sort((a, b) => b.count - a.count || a.code.localeCompare(b.code));
}

function bufferFromPayload(payload) {
    if (Buffer.isBuffer(payload)) return payload;
    if (payload instanceof ArrayBuffer) return Buffer.from(new Uint8Array(payload));
    if (ArrayBuffer.isView(payload)) return Buffer.from(payload.buffer, payload.byteOffset, payload.byteLength);
    if (Array.isArray(payload)) return Buffer.from(payload);
    if (payload && payload.type === 'Buffer' && Array.isArray(payload.data)) return Buffer.from(payload.data);
    return null;
}

function findBestSheet(workbook) {
    let best = null;
    for (const sheetName of workbook.SheetNames || []) {
        const ws = workbook.Sheets[sheetName];
        if (!ws) continue;
        const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: null, blankrows: true });
        const scanRows = Math.min(20, aoa.length);
        for (let r = 0; r < scanRows; r++) {
            const row = Array.isArray(aoa[r]) ? aoa[r] : [];
            const mapped = new Set();
            let recognized = 0;
            let nonEmpty = 0;
            for (const cell of row) {
                if (isEmpty(cell)) continue;
                nonEmpty += 1;
                const key = aliasMap.get(normalizeHeader(cell));
                if (key && !mapped.has(key)) {
                    mapped.add(key);
                    recognized += 1;
                }
            }
            const score = recognized * 100 - Math.max(0, nonEmpty - recognized);
            if (!best || score > best.score) best = { sheetName, ws, aoa, headerIndex: r, recognized, score };
        }
    }
    return best;
}

function previewRow(row) {
    return {
        row: row.source_row,
        supplier: row.supplier,
        material_name: row.material_name,
        sap_number: row.sap_number,
        batch_number: row.batch_number,
        production_date: row.production_date || row.production_date_raw,
        purchase_order_number: row.purchase_order_number,
        compression_hardness_kpa: row.compression_hardness_kpa,
        density_kg_m3: row.density_kg_m3,
        test_date: row.test_date || row.test_date_raw,
        plant: row.plant,
        inspector: row.inspector,
        remarks: row.remarks,
        issues: row.validation_issues || [],
        warning_count: (row.validation_issues || []).filter(x => x.level === 'warning').length,
        error_count: (row.validation_issues || []).filter(x => x.level === 'error').length
    };
}

function response(base) {
    msg.payload = Object.assign({
        kind: 'validation',
        siteCode,
        language,
        targetTable: SITE_TABLES[siteCode] || null,
        ok: false,
        canImport: false,
        fileName,
        sheetName: null,
        headerRow: null,
        rowCount: 0,
        errorCount: 0,
        warningCount: 0,
        errorSummary: [],
        warningSummary: [],
        details: [],
        detailTruncated: false,
        preview: [],
        previewPage: 1,
        previewPageSize: PREVIEW_PAGE_SIZE,
        previewPageCount: 0,
        candidateId: null
    }, base || {});
    delete msg.file;
    return msg;
}

const siteCode = msg.siteCode == null ? '' : String(msg.siteCode);
const language = LANGUAGES.has(String(msg.language || '').toLowerCase()) ? String(msg.language).toLowerCase() : 'de';
const fileName = msg.file && msg.file.name ? String(msg.file.name) : null;

if (!siteCode) {
    return response({ errorCount: 1, errorSummary: [{ code: 'SITE_MISSING', count: 1 }], details: [issue('error', 'SITE_MISSING')] });
}
if (!SITE_TABLES[siteCode]) {
    return response({ errorCount: 1, errorSummary: [{ code: 'SITE_INVALID', count: 1 }], details: [issue('error', 'SITE_INVALID', null, null, siteCode)] });
}
if (!fileName) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_NAME_MISSING', count: 1 }], details: [issue('error', 'FILE_NAME_MISSING')] });
}
if (!/\.xls(x)?$/i.test(fileName)) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_TYPE_INVALID', count: 1 }], details: [issue('error', 'FILE_TYPE_INVALID', null, null, fileName)] });
}
if (msg.file.size && Number(msg.file.size) > MAX_FILE_BYTES) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_TOO_LARGE', count: 1 }], details: [issue('error', 'FILE_TOO_LARGE', null, null, msg.file.size, { limitMb: 5 })] });
}

const buffer = bufferFromPayload(msg.payload);
if (!buffer) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_BUFFER_INVALID', count: 1 }], details: [issue('error', 'FILE_BUFFER_INVALID')] });
}
if (buffer.length === 0) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_EMPTY', count: 1 }], details: [issue('error', 'FILE_EMPTY')] });
}
if (buffer.length > MAX_FILE_BYTES) {
    return response({ errorCount: 1, errorSummary: [{ code: 'FILE_TOO_LARGE', count: 1 }], details: [issue('error', 'FILE_TOO_LARGE', null, null, buffer.length, { limitMb: 5 })] });
}

let workbook;
try {
    workbook = XLSX.read(buffer, { type: 'buffer', raw: true, cellDates: false, dense: false });
} catch (err) {
    return response({
        errorCount: 1,
        errorSummary: [{ code: 'FILE_PARSE_ERROR', count: 1 }],
        details: [issue('error', 'FILE_PARSE_ERROR', null, null, null, { detail: err.message || String(err) })]
    });
}

const errors = [];
const warnings = [];
const best = findBestSheet(workbook);
if (!best || best.recognized < 8) {
    errors.push(issue('error', 'SCHEMA_NOT_FOUND'));
    return response({
        sheetName: best ? best.sheetName : null,
        errorCount: errors.length,
        errorSummary: makeSummary(errors),
        details: errors
    });
}

const headerRow = best.aoa[best.headerIndex] || [];
const columnByKey = {};
const unknownHeaders = [];
const duplicateHeaders = [];

for (let c = 0; c < headerRow.length; c++) {
    const cell = headerRow[c];
    if (isEmpty(cell)) continue;
    const key = aliasMap.get(normalizeHeader(cell));
    if (!key) {
        unknownHeaders.push({ column: c + 1, value: cleanText(cell) });
        continue;
    }
    if (columnByKey[key] != null) duplicateHeaders.push({ key, column: c + 1, value: cleanText(cell) });
    else columnByKey[key] = c;
}

for (const def of FIELD_DEFS) {
    if (columnByKey[def.key] == null) {
        errors.push(issue('error', 'HEADER_MISSING', best.headerIndex + 1, def.key));
    }
}
for (const h of unknownHeaders) {
    errors.push(issue('error', 'HEADER_UNKNOWN', best.headerIndex + 1, null, h.value, { column: h.column, header: h.value }));
}
for (const h of duplicateHeaders) {
    errors.push(issue('error', 'HEADER_DUPLICATE', best.headerIndex + 1, h.key, h.value, { column: h.column }));
}

if (errors.length) {
    return response({
        sheetName: best.sheetName,
        headerRow: best.headerIndex + 1,
        errorCount: errors.length,
        errorSummary: makeSummary(errors),
        details: errors.slice(0, MAX_DETAIL_ITEMS),
        detailTruncated: errors.length > MAX_DETAIL_ITEMS
    });
}

const rows = [];
const rowFingerprints = new Map();

for (let r = best.headerIndex + 1; r < best.aoa.length; r++) {
    const excelRow = best.aoa[r] || [];
    const hasAnyData = FIELD_DEFS.some(def => !isEmpty(excelRow[columnByKey[def.key]]));
    if (!hasAnyData) continue;

    const sourceRow = r + 1;
    const rowWarnings = [];
    const rowErrors = [];
    const raw = {};
    for (const def of FIELD_DEFS) raw[def.key] = jsonSafe(excelRow[columnByKey[def.key]]);

    const supplier = cleanText(raw.supplier);
    const materialName = cleanText(raw.material_name);
    const sapNumber = cleanText(raw.sap_number);
    const batchNumber = cleanText(raw.batch_number);
    const purchaseOrderNumber = cleanText(raw.purchase_order_number);
    const plant = cleanText(raw.plant);
    const inspector = cleanText(raw.inspector);
    const remarks = cleanText(raw.remarks);

    if (!supplier) rowErrors.push(issue('error', 'REQUIRED_VALUE_MISSING', sourceRow, 'supplier', raw.supplier));
    if (!materialName) rowErrors.push(issue('error', 'REQUIRED_VALUE_MISSING', sourceRow, 'material_name', raw.material_name));
    if (!plant) rowErrors.push(issue('error', 'REQUIRED_VALUE_MISSING', sourceRow, 'plant', raw.plant));
    if (!sapNumber) rowWarnings.push(issue('warning', 'IDENTIFIER_MISSING', sourceRow, 'sap_number', raw.sap_number));
    if (!batchNumber) rowWarnings.push(issue('warning', 'IDENTIFIER_MISSING', sourceRow, 'batch_number', raw.batch_number));
    if (!purchaseOrderNumber) rowWarnings.push(issue('warning', 'IDENTIFIER_MISSING', sourceRow, 'purchase_order_number', raw.purchase_order_number));

    const hardness = parseNumber(raw.compression_hardness_kpa);
    const density = parseNumber(raw.density_kg_m3);
    if (hardness == null) rowErrors.push(issue('error', 'NUMBER_INVALID', sourceRow, 'compression_hardness_kpa', raw.compression_hardness_kpa));
    if (density == null) rowErrors.push(issue('error', 'NUMBER_INVALID', sourceRow, 'density_kg_m3', raw.density_kg_m3));
    if (hardness != null && hardness < 0) rowErrors.push(issue('error', 'NUMBER_RANGE', sourceRow, 'compression_hardness_kpa', hardness));
    if (density != null && density <= 0) rowErrors.push(issue('error', 'NUMBER_RANGE', sourceRow, 'density_kg_m3', density));
    if (hardness === 0) rowWarnings.push(issue('warning', 'NUMBER_SUSPICIOUS', sourceRow, 'compression_hardness_kpa', hardness));

    const production = parseDate(raw.production_date, sourceRow, 'production_date', rowWarnings);
    const test = parseDate(raw.test_date, sourceRow, 'test_date', rowWarnings);
    if (!production.raw) rowWarnings.push(issue('warning', 'DATE_MISSING', sourceRow, 'production_date'));
    if (!test.raw) rowWarnings.push(issue('warning', 'DATE_MISSING', sourceRow, 'test_date'));
    if (compareIso(production.iso, test.iso) > 0) {
        rowWarnings.push(issue('warning', 'DATE_SEQUENCE', sourceRow, 'production_date', production.raw, { production: production.iso, test: test.iso }));
    }

    const rowObject = {
        source_row: sourceRow,
        supplier,
        material_name: materialName,
        sap_number: sapNumber,
        batch_number: batchNumber,
        production_date: production.iso,
        production_date_raw: production.raw,
        purchase_order_number: purchaseOrderNumber,
        compression_hardness_kpa: hardness,
        density_kg_m3: density,
        test_date: test.iso,
        test_date_raw: test.raw,
        plant,
        inspector,
        remarks,
        validation_warnings: [],
        validation_issues: [],
        source_row_json: raw
    };

    const fingerprint = JSON.stringify([
        supplier, materialName, sapNumber, batchNumber, production.raw,
        purchaseOrderNumber, hardness, density, test.raw, plant, inspector, remarks
    ]);
    if (rowFingerprints.has(fingerprint)) {
        const firstRow = rowFingerprints.get(fingerprint);
        rowWarnings.push(issue('warning', 'DUPLICATE_ROW', sourceRow, null, null, { firstRow }));
    } else {
        rowFingerprints.set(fingerprint, sourceRow);
    }

    rowObject.validation_warnings = rowWarnings.map(w => ({ code: w.code, field: w.field, value: w.value, params: w.params }));
    rowObject.validation_issues = [...rowErrors, ...rowWarnings];
    errors.push(...rowErrors);
    warnings.push(...rowWarnings);
    rows.push(rowObject);
}

if (rows.length === 0) errors.push(issue('error', 'NO_DATA_ROWS'));

const now = Date.now();
let candidates = flow.get('foamImportCandidates') || {};
for (const [key, candidate] of Object.entries(candidates)) {
    if (!candidate || !candidate.createdAt || now - candidate.createdAt > CANDIDATE_TTL_MS) delete candidates[key];
}

let candidateId = null;
if (rows.length > 0) {
    candidateId = `${siteCode}-${now.toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
    candidates[candidateId] = {
        createdAt: now,
        siteCode,
        targetTable: SITE_TABLES[siteCode],
        language,
        fileName,
        sheetName: best.sheetName,
        rowCount: rows.length,
        warningCount: warnings.length,
        errorCount: errors.length,
        canImport: errors.length === 0,
        rows
    };
    flow.set('foamImportCandidates', candidates);
}

return response({
    ok: errors.length === 0,
    canImport: errors.length === 0,
    sheetName: best.sheetName,
    headerRow: best.headerIndex + 1,
    rowCount: rows.length,
    errorCount: errors.length,
    warningCount: warnings.length,
    errorSummary: makeSummary(errors),
    warningSummary: makeSummary(warnings),
    details: [...errors, ...warnings].slice(0, MAX_DETAIL_ITEMS),
    detailTruncated: errors.length + warnings.length > MAX_DETAIL_ITEMS,
    preview: rows.slice(0, PREVIEW_PAGE_SIZE).map(previewRow),
    previewPage: 1,
    previewPageSize: PREVIEW_PAGE_SIZE,
    previewPageCount: rows.length ? Math.ceil(rows.length / PREVIEW_PAGE_SIZE) : 0,
    candidateId
});

// Node-RED Function node body, 2 outputs:
// [0] PostgreSQL call, [1] immediate UI error
const candidates = flow.get('foamImportCandidates') || {};
const candidateId = msg.candidateId || (msg.payload && msg.payload.candidateId);
const candidate = candidateId ? candidates[candidateId] : null;

function fail(messageCode) {
    msg.payload = { kind: 'import_result', ok: false, messageCode, siteCode: candidate ? candidate.siteCode : null };
    return [null, msg];
}

if (!candidate) return fail('CANDIDATE_MISSING');

const ageMs = Date.now() - candidate.createdAt;
if (ageMs > 30 * 60 * 1000) {
    delete candidates[candidateId];
    flow.set('foamImportCandidates', candidates);
    return fail('CANDIDATE_EXPIRED');
}
if (!candidate.canImport || candidate.errorCount > 0) return fail('CANDIDATE_BLOCKED');

const importedBy = (msg._client && msg._client.user && msg._client.user.username)
    ? String(msg._client.user.username)
    : null;

msg.params = [
    candidate.siteCode,
    candidate.fileName,
    candidate.sheetName,
    candidate.rowCount,
    candidate.warningCount,
    JSON.stringify(candidate.rows),
    importedBy
];
msg._candidateId = candidateId;
msg._candidateSiteCode = candidate.siteCode;
msg._candidateFileName = candidate.fileName;
msg._candidateRowCount = candidate.rowCount;
msg._candidateWarningCount = candidate.warningCount;
return [msg, null];

// Node-RED Function node body
const result = Array.isArray(msg.payload) && msg.payload.length ? msg.payload[0] : {};
const candidates = flow.get('foamImportCandidates') || {};
if (msg._candidateId && candidates[msg._candidateId]) {
    delete candidates[msg._candidateId];
    flow.set('foamImportCandidates', candidates);
}

msg.payload = {
    kind: 'import_result',
    ok: true,
    messageCode: 'IMPORT_SUCCESS',
    siteCode: msg._candidateSiteCode || result.site_code || null,
