// Node-RED Function node body, 2 outputs:
// [0] enriched file upload -> validator, [1] UI settings -> result/template
const ALLOWED_SITES = new Set(['2000', '5000', '8200']);
const ALLOWED_LANGUAGES = new Set(['de', 'pl', 'ro']);
const DEFAULT_LANGUAGE_BY_SITE = { '2000':'de', '5000':'de', '8200':'de' };
const DEFAULT_SETTINGS = { siteCode: '2000', language: 'de' };

function clientKey(m) {
    const c = m._client || {};
    if (c.socketId) return String(c.socketId);
    if (c.id) return String(c.id);
    if (c.user && c.user.username) return `user:${c.user.username}`;
    return 'anonymous';
}

const key = clientKey(msg);
let settingsByClient = flow.get('foamUiSettings') || {};
const payload = msg.payload;

if (payload && typeof payload === 'object' && payload.kind === 'ui_settings') {
    const previous = settingsByClient[key] || DEFAULT_SETTINGS;

    const siteCode = ALLOWED_SITES.has(String(payload.siteCode || ''))
        ? String(payload.siteCode)
        : DEFAULT_SETTINGS.siteCode;

    const siteChanged = previous.siteCode !== siteCode;
    const reason = payload.reason || 'change';

    let language;

    // Bei einem echten Site-Wechsel immer den Site-Default setzen
    if (siteChanged && reason === 'site_change') {
        language = DEFAULT_LANGUAGE_BY_SITE[siteCode] || 'de';
    } else {
        // Bei manueller Sprachänderung die gewählte Sprache übernehmen
        const requestedLanguage = String(payload.language || '').toLowerCase();

        language = ALLOWED_LANGUAGES.has(requestedLanguage)
            ? requestedLanguage
            : (
                previous.language ||
                DEFAULT_LANGUAGE_BY_SITE[siteCode] ||
                'de'
            );
    }

    settingsByClient[key] = {
        siteCode,
        language,
        updatedAt: Date.now()
    };

    flow.set('foamUiSettings', settingsByClient);

    msg.payload = {
        kind: 'ui_settings',
        siteCode,
        language,
        reason,
        siteChanged
    };

    return [null, msg];
}

// Custom upload sends site/language explicitly. Prefer these values so site changes
// immediately before file selection cannot race with the settings message.
const explicitSite = ALLOWED_SITES.has(String(msg.siteCode || '')) ? String(msg.siteCode) : null;
const explicitLanguageRaw = String(msg.language || '').toLowerCase();
const explicitLanguage = ALLOWED_LANGUAGES.has(explicitLanguageRaw) ? explicitLanguageRaw : null;
const current = settingsByClient[key] || DEFAULT_SETTINGS;
const siteCode = explicitSite || current.siteCode;
const language = explicitLanguage || current.language || DEFAULT_LANGUAGE_BY_SITE[siteCode] || 'de';
settingsByClient[key] = { siteCode, language, updatedAt: Date.now() };
flow.set('foamUiSettings', settingsByClient);
msg.siteCode = siteCode;
msg.language = language;
return [msg, null];

// Node-RED Function node body
const PAGE_SIZE = 25;
const CANDIDATE_TTL_MS = 30 * 60 * 1000;
const candidates = flow.get('foamImportCandidates') || {};
const payload = msg.payload || {};
const candidateId = payload.candidateId;
const candidate = candidateId ? candidates[candidateId] : null;

function previewRow(row) {
    return {
        row: row.source_row,
        supplier: row.supplier,
        material_name: row.material_name,
        sap_number: row.sap_number,
        batch_number: row.batch_number,
        production_date: row.production_date || row.production_date_raw,
        purchase_order_number: row.purchase_order_number,
        compression_hardness_kpa: row.compression_hardness_kpa,
        density_kg_m3: row.density_kg_m3,
        test_date: row.test_date || row.test_date_raw,
        plant: row.plant,
        inspector: row.inspector,
        remarks: row.remarks,
        issues: row.validation_issues || [],
        warning_count: (row.validation_issues || []).filter(x => x.level === 'warning').length,
        error_count: (row.validation_issues || []).filter(x => x.level === 'error').length
    };
}

if (!candidate) {
    msg.payload = { kind: 'preview_page', ok: false, messageCode: 'CANDIDATE_MISSING', candidateId: candidateId || null };
    return msg;
}
if (Date.now() - candidate.createdAt > CANDIDATE_TTL_MS) {
    delete candidates[candidateId];
    flow.set('foamImportCandidates', candidates);
    msg.payload = { kind: 'preview_page', ok: false, messageCode: 'CANDIDATE_EXPIRED', candidateId };
    return msg;
}

const pageCount = Math.max(1, Math.ceil(candidate.rows.length / PAGE_SIZE));
let page = Number(payload.page || 1);
if (!Number.isInteger(page)) page = 1;
page = Math.max(1, Math.min(page, pageCount));
const start = (page - 1) * PAGE_SIZE;

msg.payload = {
    kind: 'preview_page',
    ok: true,
    candidateId,
    siteCode: candidate.siteCode,
    page,
    pageSize: PAGE_SIZE,
    pageCount,
    rowCount: candidate.rows.length,
    preview: candidate.rows.slice(start, start + PAGE_SIZE).map(previewRow)
};
return msg;
